typedef float vm_num_t;

class vm_stack
{
public:
    bool push(const char* src, int n);
};

class script_library_class
{
public:
    class function
    {
    public:
        enum entry_t
        {
            FIRST_ENTRY,
            RECALL_ENTRY
        };

        virtual ~function();
        virtual bool operator()(vm_stack& stack, entry_t entry);
    };
};

class input_mgr
{
public:
    enum device_id_t
    {
        JOYSTICK_DEVICE = 1
    };

    static input_mgr* instance;

    static input_mgr* inst()
    {
        return instance;
    }

    float get_control_delta(device_id_t device, int control) const;
};

class game
{
public:
    char pad[200];
    unsigned long long flags;
    char pad2[180];
    int active_player;

    bool is_hero_frozen() const
    {
        return (flags >> 34) & 1;
    }

    int get_active_player() const
    {
        return active_player;
    }
};

class app
{
public:
    char pad[16];
    game* the_game;

    static app* instance;

    static app* inst()
    {
        return instance;
    }

    game* get_game()
    {
        return the_game;
    }
};

class hero
{
public:
    char pad[384];
    int suspended;

    bool is_suspended() const
    {
        return suspended;
    }
};

class world_dynamics_system
{
public:
    char pad[6796];
    struct hero_slot
    {
        char pad[240];
        hero* value;
    } heroes[2];

    hero* get_hero_ptr(int player)
    {
        return heroes[player].value;
    }
};

extern world_dynamics_system* g_world_ptr;
extern game* g_game_ptr;
extern void error(const char*);

enum
{
    PLAYER_ACTION = 34
};

#define AXIS_MAX 1.0f
#define SLF_RETURN \
    if (!stack.push((char*)&result, sizeof(result))) \
        error("script stack overflow")
#define SLF_DONE return true

class slf_is_action_button_down_t : public script_library_class::function
{
public:
    virtual bool operator()(vm_stack& stack, entry_t entry);
};

bool slf_is_action_button_down_t::operator()(vm_stack& stack, entry_t entry)
{
      vm_num_t result = (input_mgr::inst()->get_control_delta( JOYSTICK_DEVICE, PLAYER_ACTION ) == AXIS_MAX &&
						!app::inst()->get_game()->is_hero_frozen() &&
//!						!g_world_ptr->get_hero_ptr()->get_paralysis_factor() &&
						!g_world_ptr->get_hero_ptr(g_game_ptr->get_active_player())->is_suspended());

//      vm_num_t result = g_world_ptr->get_hero_ptr()->get_sheathe_state()*input_mgr::inst()->get_control_state( JOYSTICK_DEVICE, PLAYER_ACTION );
      SLF_RETURN;
      SLF_DONE;
}
